/*
 * DCBalanceReference.h
 *
 * Per-level growth factors from the world table `dc_balance_reference`.
 *
 * DarkChaos keeps levels 1-80 as WotLK and, above 80, holds each ratio at the
 * value it has at 80 (rage per hit, pet damage against owner damage, ...). A
 * ratio can only be held if something says how much the other side grew since
 * 80, and that is this table: one row per level, every column 1.0 at level 80.
 * The rows are generated by tools/balance/gen_reference.py from the gear ladder.
 *
 * It lives in the game library because core formulas (Unit::RewardRage) read
 * it, and the scripts library cannot be reached from there.
 */

#ifndef DC_BALANCE_REFERENCE_H
#define DC_BALANCE_REFERENCE_H

#include "Define.h"

namespace DarkChaos
{
    namespace BalanceReference
    {
        // Growth against level 80.
        struct Growth
        {
            float gear = 1.0f;      // stamina / primary stat on one armour piece
            float weapon = 1.0f;    // weapon damage per second
            float health = 1.0f;    // reference player health
            float melee = 1.0f;     // size of one white melee hit
        };

        // Reads the table. World thread, once at startup, before any player is
        // in world; the rows are read-only afterwards, so map threads may call
        // Find() without locking. A missing table is not an error: the SQL file
        // that creates it may not be applied yet, and every reader then keeps
        // its stock formula.
        void Load();

        // The row for `level`, or nullptr when there is none (table missing or
        // empty, or a level below 80). Always check: nullptr means "use the
        // stock behaviour".
        Growth const* Find(uint8 level);

        // Re-reads the config keys this module owns (DC.Balance.*). World
        // thread; called at startup and on every config reload.
        void LoadConfig();

        // Creature spells that scale with creature level are multiplied by the
        // ratio of two rows of the creature damage table. Above level 80 that
        // table was ramped steeply to make melee work, and spells inherited
        // the ramp without the per-creature correction melee got: a level-140
        // creature's classic bolt took a sixth of a player's health.
        //
        // This limits one side of that ratio. Up to level 80 it returns
        // `power` unchanged. Above it the result is at most the level-80
        // table value grown by reference player health, times
        // DC.Balance.CreatureSpellScale. It never raises `power`, and it
        // changes nothing without a reference row or with the key set to 0.
        float CapCreatureSpellPower(float power, float powerAtLevel80, uint8 level);

        // Spells of player-owned creatures (pets, guardians, totems) that have
        // no rank to grow into above 80 -- Waterbolt, Mirror Image, the Snake
        // Trap poisons -- keep their level-80 amount there. The caller holds
        // such an amount at its level-80 value and multiplies it by this: the
        // growth a whole class spell hit gets (a white hit's for damage,
        // reference health for heals and absorbs). The spell power part of a
        // guardian's hit grows with its owner's gear on top; it is small for
        // these spells (coefficients 0.15-0.45 on a share of the owner's
        // spell power), so the base points carry the hit. Returns 0 when
        // nothing applies: level 80 or below, no reference row, or
        // DC.Balance.GuardianSpells = 0.
        float GuardianSpellGrowth(uint8 level, bool heal);

        // A named guardian (Army of the Dead ghoul, Shadowfiend, Treant,
        // Spirit Wolf, the shaman elementals, ...) takes its weapon damage
        // from a formula of its level alone, such as "level +/- 25%". That is
        // WotLK up to 80, but it only doubles between 80 and 160 while a
        // player's white hit grows ninefold, so the guardian's share of its
        // owner's damage falls to a third. Above 80 the caller evaluates the
        // formula at `formulaLevel` and multiplies the result by `growth`
        // (a white hit's growth). The part of the swing that comes from the
        // owner's attack or spell power is left alone: it grows with the
        // owner's gear. At level 80 and below, without a reference row, or
        // with DC.Balance.GuardianMelee = 0, this returns the level itself
        // and a growth of 1, which is the stock formula.
        struct GuardianMelee
        {
            uint8 formulaLevel;
            float growth;
        };
        GuardianMelee GuardianMeleeGrowth(uint8 level);

        // Some attacks are a share of the attacker's attack power and
        // nothing else: Bloodthirst, Victory Rush, the death knight
        // diseases, a paladin's judgements, the swing of the ghoul. WotLK
        // gives them no rank past the first, because attack power carries
        // them. Above level 80 attack power grows about half as fast as a
        // white hit does (weapon damage outgrows it), so by 150 they hit for
        // half of what a spec's ranked attacks do. Most of them are fixed
        // spell ids the core casts by number, so a higher rank cannot be
        // taught either.
        //
        // IsPowerAbility says whether a damage spell is one of them, and the
        // caller multiplies its damage by PowerAbilityGrowth: a white hit's
        // growth divided by the reference attack power's growth. That is
        // 1.0 at level 80 and below, without a reference row, or with
        // DC.Balance.PowerAbilities = 0.
        bool IsPowerAbility(uint32 spellId);
        float PowerAbilityGrowth(uint8 level);
    }
}

#endif
